import{_ as s,l,o as e,c as n,v as t,p as i,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"只读事务与快照","description":"","frontmatter":{"title":"只读事务与快照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/read-only-snapshot.md","filePath":"cs/read-only-snapshot.md","lastUpdated":1789023840000}'),E={name:"cs/read-only-snapshot.md"};function h(A,a,_,B,m,u){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="只读事务与快照" tabindex="-1">只读事务与快照 <a class="header-anchor" href="#只读事务与快照" aria-label="Permalink to &quot;只读事务与快照&quot;">​</a></h1><div class="epigraph"><p>只读事务不安装写集，快照可在开始时钉死；读不阻塞写，但钉住的水位仍可能挡住 GC，除非快照被送到副本。</p><footer>—— 据 Fekete 等 SI；Postgres REPEATABLE READ；异步备库只读</footer></div><p><a href="/cs/mvcc-gc">上一课</a>把膨胀归到最小快照。本课专讲只读：主干隔离级别有只读优化。缺口是<strong>声明只读</strong>带来的协议变体：无写锁、无 OCC 验证写集、可在备库执行、可与 SSI 豁免交互。Calvin 下一课连写也确定性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读写事务的快照若在第一句才钉，可与 SI 异常相关；有的引擎事务开始即钉。只读：开始钉即可。缺口是一致性：只读要不要看见「自己开始后已提交的写」——不可重复读 vs 语句快照 vs 事务快照。分析查询要事务快照才可重复。</p><p>备库只读：物理复制延迟，读的是过去快照，GC 在主库若无 feedback 可不被备库查询钉住（备库自己 vacuum）。冲突：主库 replay 与备库查询锁行，hot standby 冲突。</p><p><span class="marginnote">只读优化不能改成脏读。读己之写在单机只读事务无写。分布式读己之写后课复制延迟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>BEGIN READ ONLY</code>：锁管理器不发 IX，优化器可选延迟物化与无间隙锁（在 SI 下）。导出快照 id 给其他连接（快照导入）做多会话一致读，水位仍钉。</p><p>HTAP：分析只读走列存副本，OLTP 走行存，快照由复制 LSN 对齐——后课 HTAP。</p>',10)),(e(),i(c,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RO%5B%22%E5%8F%AA%E8%AF%BB%E5%BC%80%E5%A7%8B%22%5D%20--%3E%20PIN%5B%22%E9%92%89%E5%BF%AB%E7%85%A7%22%5D%0A%20%20PIN%20--%3E%20READ%5B%22%E6%97%A0%E5%86%99%E9%94%81%E6%89%AB%E6%8F%8F%22%5D%0A%20%20PIN%20--%3E%20GC%5B%22%E4%BB%8D%E5%8F%AF%E8%83%BD%E9%92%89%20xmin%22%5D%0A%20%20REPL%5B%22%E5%A4%87%E5%BA%93%E5%8F%AA%E8%AF%BB%22%5D%20--%3E%20LAG%5B%22%E9%99%88%E6%97%A7%E4%BD%86%E5%B0%91%E6%8C%A1%E4%B8%BB%E5%BA%93%20GC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>计划：只读可串行在 SSI 下少 abort。并行工人共享同一快照号，否则各工人看见不同提交。exchange 课已要求。</p><p>与预编译：只读短查询仍走计划缓存；快照号每次新。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Calvin 定序。也不把只读当最终一致 OK 的借口——合同要写陈旧预算。RTO 是恢复课。</p><p>后课默认：分析用事务快照只读；怕膨胀则走副本。Calvin 确定性：先全局定序再无锁执行，读写都适用。</p><p>只读不是隔离级别，是事务属性；与 RR/SSI 正交组合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>只读钉快照、少锁；仍可能钉 GC 水位。</li><li>备库只读用延迟换主库膨胀。</li><li>Calvin 确定性下一课：定序代替冲突检测。</li><li>出处：SI 文献；Postgres 只读/备库；Gray。</li></ul>',9))])}const f=s(E,[["render",h]]);export{S as __pageData,f as default};
